import {parseTable,TABLE_EXAMPLE} from '../adapters/universal.js';
import {prepareImport} from '../core/import-plan.js';
import {validateEnvelope,validateSettings,DEFAULT_TIMES,conflicts,toICS} from '../core/model.js';
import {importData} from '../adapters/registry.js';import '../adapters/zfsoft.js';
import {parseSchoolPDF} from '../adapters/school-pdf.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupDataTools({get,apply,notify,openSheet}){
 let pending;
 function preview(value){const current=get(),plan=prepareImport(current.demo?[]:current.courses,value);pending=plan.value;const changes=compare(current.demo?[]:current.courses,pending.courses),collision=conflicts(pending.courses);$('#import-summary').innerHTML=`<p>${E(value.adapter||'课表备份')} · <b>${plan.records.length} 条排课</b> / ${new Set(plan.records.map(c=>c.name)).size} 门课程</p><p>新增 ${changes.added} · 移除 ${changes.removed} · 完全相同 ${changes.same}<br>冲突 ${collision.length} 处。${E(plan.message)}</p>${value.settings?'':'<p>将沿用当前开学日期和作息。导入数据没有提供钟点时间，请在「学期与作息」核对。</p>'}${(value.warnings||[]).map(w=>`<p>未排入时间表：${E(w)}</p>`).join('')}`;$('#import-records').innerHTML=plan.records.map(c=>`<p><b>${E(c.name)}</b><br><small>周${c.day} · ${c.start}–${c.end}节 · ${E(c.weeks.join('、'))}周<br>${E(c.location)} · ${E(c.teacher)}</small></p>`).join('');$('#confirm-import').disabled=false;openSheet('#import-sheet');}
 function receive(text){try{const value=importData(typeof text==='string'?JSON.parse(text):text);preview(value);return {ok:true,count:value.courses.length};}catch(e){notify(e.message);return {ok:false,error:e.message};}}
 window.receiveSchoolData=receive;window.onNativeExportResult=notify;window.onSchoolSyncStatus=message=>{const el=$('#native-status');if(el)el.textContent=message;};
 $('#import-file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw Error('文件超过 20 MB');notify('正在本机解析课表…');const value=/\.pdf$/i.test(file.name)||file.type==='application/pdf'?await parseSchoolPDF(new Uint8Array(await file.arrayBuffer()),notify):(/\.csv$/i.test(file.name)?parseTable(await file.text()):importData(JSON.parse(await file.text())));preview(value);}catch(e){notify(e.message);}};
 $('#confirm-import').onclick=()=>{if(!pending)return;try{const current=get(),value=validateEnvelope({...pending,settings:pending.settings||current.settings,demo:false});localStorage.setItem('course-compass.v1',JSON.stringify(value));if(!apply())throw Error('导入数据无法重新读取');localStorage.setItem('course-compass.lastImport',new Date().toISOString());$('#import-sheet').close();notify('课表已更新，个人安排已保留');pending=null;}catch(e){notify(e.message);}};
 function download(name,mime,text){if(window.CourseCompass?.saveFile){window.CourseCompass.saveFile(name,mime,text);return;}const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
 function term(){const {settings}=get(),f=$('#term-form');f.elements.term.value=settings.term;f.elements.startDate.value=settings.startDate;f.elements.totalWeeks.value=settings.totalWeeks;$('#period-inputs').innerHTML=settings.times.map((v,i)=>`<label>第 ${i+1} 节<input name="time${i}" value="${E(v)}" placeholder="08:20-09:05" required></label>`).join('');$('#term-error').textContent='';openSheet('#term-sheet');}
 $('#school-times').onclick=()=>{DEFAULT_TIMES.forEach((v,i)=>$('#term-form').elements['time'+i].value=v);notify('已填入截图作息，点击保存后生效');};
 $('#term-form').onsubmit=e=>{e.preventDefault();try{const fields=Object.fromEntries(new FormData(e.target)),current=get(),settings=validateSettings({...fields,times:Array.from({length:12},(_,i)=>fields['time'+i])});localStorage.setItem('course-compass.v1',JSON.stringify({version:1,courses:current.courses,settings,demo:current.demo}));apply();$('#term-sheet').close();notify('学期与作息已保存');}catch(e){$('#term-error').textContent=e.message;}};
 $('#table-example').onclick=()=>{$('#table-text').value=TABLE_EXAMPLE;};
 $('#table-parse').onclick=()=>{try{preview(parseTable($('#table-text').value));}catch(e){$('#table-error').textContent=e.message;}};
 document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;try{if(action==='table'){$('#table-error').textContent='';openSheet('#table-sheet');}if(action==='import')$('#import-file').click();if(action==='term')term();if(action==='backup'){const current=get();download('课间-课表备份.json','application/json',JSON.stringify({version:1,...current},null,2));}if(action==='calendar')download('课间-课程日历.ics','text/calendar',toICS(get().courses,get().settings));if(action==='login')window.CourseCompass?.openPortal();if(action==='sync')window.CourseCompass?.syncPortal();}catch(error){notify(error.message);}});
 return {receive};
}
function compare(old,next){const key=c=>JSON.stringify([c.name,c.day,c.start,c.end,c.weeks,c.location,c.teacher]),before=new Map();for(const c of old){const k=key(c);before.set(k,(before.get(k)||0)+1);}let same=0,added=0;for(const c of next){const k=key(c),count=before.get(k)||0;if(count){same++;before.set(k,count-1);}else added++;}return {same,added,removed:[...before.values()].reduce((a,b)=>a+b,0)};}
